#include "UnifiedTriggerOrchestrator.hpp"
namespace RawrXD::Governance{UnifiedTriggerOrchestrator::UnifiedTriggerOrchestrator(OrchestratorCallbacks c):cb_(std::move(c)){}UnifiedTriggerOrchestrator::~UnifiedTriggerOrchestrator(){stop();}bool UnifiedTriggerOrchestrator::initialize(){auto p=evaluate(Trigger::ColdBoot);return p.hardware.total_ram_bytes!=0;}RuntimePlan UnifiedTriggerOrchestrator::evaluate(Trigger trigger){auto hw=probe_.probe();auto cap=matrix_.resolve(hw);governor_.update(hw,cap.policy.tier);uint32_t ctx=cb_.context_tokens?(uint32_t)cb_.context_tokens():0;auto pd=pressure_.evaluate(hw.total_ram_bytes,hw.available_ram_bytes,ctx);pressure_.cycle();TLSInstructionGate::install(hw.cpu);RuntimePlan n;n.hardware=hw;n.capability=cap;n.effective_tier=governor_.effective_tier();n.pressure=pd;n.instruction_path=TLSInstructionGate::path();n.use_ensemble=cap.policy.allow_ensemble&&(unsigned)n.effective_tier>=(unsigned)CapabilityTier::High;n.reason=pd.emergency_halt?"critical memory pressure":trigger==Trigger::HardwareChange?"hardware change":cap.reason;bool changed=last_hw_.timestamp_ns==0||hw.materially_changed_from(last_hw_);{std::lock_guard<std::mutex>l(mu_);plan_=n;last_hw_=hw;}if(cb_.apply_plan&&(changed||trigger!=Trigger::Periodic))cb_.apply_plan(n);return n;}void UnifiedTriggerOrchestrator::start(std::chrono::milliseconds period){if(running_.exchange(true))return;worker_=std::thread([this,period]{loop(period);});}void UnifiedTriggerOrchestrator::stop(){if(!running_.exchange(false))return;if(worker_.joinable())worker_.join();}void UnifiedTriggerOrchestrator::loop(std::chrono::milliseconds p){while(running_){auto before=last_hw_;auto n=evaluate(Trigger::Periodic);if(before.timestamp_ns&&n.hardware.materially_changed_from(before))evaluate(Trigger::HardwareChange);std::this_thread::sleep_for(p);}}RuntimePlan UnifiedTriggerOrchestrator::snapshot()const{std::lock_guard<std::mutex>l(mu_);return plan_;}}
